func:
flow.set("auto", true);
flow.set("remoto", false);
flow.set("remoto_cnc", null);
flow.set("paro", false);
flow.set("ldr", 100);
flow.set("avance", 50);
return [
  { payload: true },
  { payload: false },
  { payload: "En LOCAL: active Modo Remoto para operar a distancia" },
  { payload: "Esperando ESP32-A (172.20.10.2:502)..." },
  { payload: 0 }
];

const r = msg.payload.data || msg.payload;
let s = {};
s.pos_pieza_pct     = Math.round((r[0] * 100 / 4095) * 100) / 100;
s.temp_husillo_C    = Math.round((r[1] * 120 / 4095) * 100) / 100;
s.vibracion_mm_s    = Math.round((r[2] * 10  / 4095) * 100) / 100;
s.corriente_banda_A = Math.round((r[3] * 5   / 4095) * 100) / 100;
s.ciclo_hr7       = r[7];
s.sensor_entrada  = r[8];
s.sensor_cnc      = r[9];
s.pieza_terminada = r[10];

flow.set("sensores", s);
flow.set("ultimo_hr7_ts", Date.now());
msg.payload = s;
return msg;

const s = msg.payload;
msg.payload = `Entrada (HR8): ${s.sensor_entrada} | CNC (HR9): ${s.sensor_cnc} | Salida (HR10): ${s.pieza_terminada} | Vib (HR2): ${s.vibracion_mm_s.toFixed(1)} mm/s`;
return msg;

const r = msg.payload.data || msg.payload;
if (!Array.isArray(r) || r.length < 3) return null;
const ldr = Math.max(0, Math.min(100, Number(r[0])));
const paro = Number(r[2]) === 1;
flow.set("ldr", ldr);
flow.set("paro", paro);
return [
  { payload: ldr },
  { payload: paro ? "PARO ACTIVO (1) — GPIO25 abierto" : "OK (0) — Listo para operar" }
];

const r = msg.payload.data || msg.payload;
if (!Array.isArray(r) || r.length < 1) return null;
const av = Math.max(0, Math.min(100, Number(r[0])));
flow.set("avance", av);
return { payload: av };

const s = msg.payload;
const ahora = Date.now();
const auto = flow.get("auto") !== false;
const paro = flow.get("paro") === true;
const avance = Number(flow.get("avance") ?? 50);
const ldr = Number(flow.get("ldr") ?? 80);
const remotoCnc = flow.get("remoto_cnc");

let c = context.get("c") || { fase: "espera", t0: 0, dur: 7000, piezas: 0, prev: 0 };
if (s.pieza_terminada === 1 && c.prev === 0) c.piezas++;
c.prev = s.pieza_terminada;

let refri = context.get("refri") || false;
if (s.temp_husillo_C > 55) refri = true;
else if (s.temp_husillo_C < 42) refri = false;
context.set("refri", refri);

let banda = 0, cnc = 0;
if (paro || s.temp_husillo_C > 72) {
    c.fase = "paro";
} else if (remotoCnc !== null && remotoCnc !== undefined && flow.get("remoto") === true) {
    cnc = remotoCnc;
} else if (auto) {
    if (s.sensor_cnc === 1) {
        if (c.fase !== "cnc" && c.fase !== "fin") { c.fase = "cnc"; c.t0 = ahora; c.dur = 2000 + avance * 100; }
        if (c.fase === "cnc") { if (ahora - c.t0 < c.dur) cnc = 1; else c.fase = "fin"; }
    } else if (s.sensor_entrada === 1 || (s.pos_pieza_pct > 0 && s.pos_pieza_pct < 100) || ldr < 40) {
        c.fase = "banda"; banda = 1;
    } else {
        c.fase = "espera";
    }
}
context.set("c", c);
flow.set("cnc_on", cnc === 1);

let alarma = "Normal";
if (paro) alarma = "PARO";
else if (s.temp_husillo_C > 72) alarma = "HH (muy alta)";
else if (c.fase === "cnc" && ahora - c.t0 > 12000) alarma = "ATASCO";
else if (s.temp_husillo_C > 65) alarma = "H (alta)";

const txtEstado = { payload: `fase: ${c.fase} | temp: ${s.temp_husillo_C.toFixed(1)} °C | refri: ${refri ? "ON" : "OFF"} | ${alarma}` };
const txtPiezas = { payload: `${c.piezas} (t = ${(2 + avance / 10).toFixed(1)} s)` };
const txtLedA   = { payload: banda ? "ENCENDIDO" : "APAGADO" };
const txtLedB   = { payload: cnc ? "ENCENDIDO" : "APAGADO" };

if (!auto && !paro && (remotoCnc === null || remotoCnc === undefined)) return [null, null, null, txtEstado, txtPiezas, txtLedA, txtLedB];
return [{ payload: banda }, { payload: cnc }, { payload: refri ? 1 : 0 }, txtEstado, txtPiezas, txtLedA, txtLedB];

const rem = msg.payload === true;
flow.set("remoto", rem);
if (!rem) flow.set("remoto_cnc", null);
return { payload: rem ? "Modo REMOTO: pulse 1. Habilitar (10s) y luego 2. Encender CNC" : "En LOCAL: active Modo Remoto para operar a distancia" };

flow.set("habilitado", true);
setTimeout(() => flow.set("habilitado", false), 10000);
return { payload: "Habilitado por 10 s -> pulse 2. Encender CNC" };

const s = flow.get("sensores") || {};
const commOk = (Date.now() - (flow.get("ultimo_hr7_ts") || 0)) <= 5000;
let res = "aceptada";
if (!commOk)                      res = "rechazada: sin comunicacion";
else if (flow.get("paro"))        res = "rechazada: paro de emergencia";
else if (!flow.get("remoto"))     res = "rechazada: modo local";
else if (!flow.get("habilitado")) res = "rechazada: sin habilitar";
else if (s.temp_husillo_C > 70)   res = "rechazada: interbloqueo (temp > 70 °C)";

flow.set("habilitado", false);
if (res === "aceptada") flow.set("remoto_cnc", 1);
const ev = { topic: `INSERT INTO eventos (ts, origen, accion, resultado) VALUES (datetime('now','localtime'), 'dashboard', 'encender cnc_on', '${res}')` };
return [res === "aceptada" ? { payload: 1 } : null, ev, { payload: res }];

const v = msg.payload.temp_husillo_C;
const activo = v > 72 ? "HH" : (v > 65 ? "H" : null);
let al = flow.get("alarma") || { estado: "normal", tipo: null };
const antes = al.estado + "/" + al.tipo;

if (activo) {
    if (al.estado === "normal" || al.estado === "normalizada_sin_reconocer" || al.tipo !== activo) {
        al = { estado: "sin_reconocer", tipo: activo };
    }
} else {
    if (al.estado === "reconocida") al = { estado: "normal", tipo: null };
    else if (al.estado === "sin_reconocer") al = { estado: "normalizada_sin_reconocer", tipo: al.tipo };
}
flow.set("alarma", al);

const texto = { payload: "Alarma: " + al.estado + (al.tipo ? " (" + al.tipo + ")" : "") };
const cambio = (al.estado + "/" + al.tipo) !== antes;
const reg = cambio ? { topic: `INSERT INTO alarmas (ts, variable, tipo, estado) VALUES (datetime('now','localtime'), 'temp_husillo_C', '${al.tipo || "-"}', '${al.estado}')` } : null;
return [texto, reg];

let al = flow.get("alarma") || { estado: "normal", tipo: null };
if (al.estado === "sin_reconocer") al.estado = "reconocida";
else if (al.estado === "normalizada_sin_reconocer") al = { estado: "normal", tipo: null };
else return null;
flow.set("alarma", al);
return [
    { payload: "Alarma: " + al.estado + (al.tipo ? " (" + al.tipo + ")" : "") },
    { topic: `INSERT INTO alarmas (ts, variable, tipo, estado) VALUES (datetime('now','localtime'), 'ACK', '${al.tipo || "-"}', '${al.estado}')` }
];

return [[
  { topic: "CREATE TABLE IF NOT EXISTS lecturas (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, variable TEXT NOT NULL, valor REAL NOT NULL)" },
  { topic: "CREATE TABLE IF NOT EXISTS eventos (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, origen TEXT, accion TEXT, resultado TEXT)" },
  { topic: "CREATE TABLE IF NOT EXISTS alarmas (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT, variable TEXT, tipo TEXT, estado TEXT)" }
]];

const s = flow.get("sensores");
if (!s || isNaN(s.temp_husillo_C)) return null;
return { topic: `INSERT INTO lecturas (ts, variable, valor) VALUES (datetime('now','localtime'), 'temp_husillo_C', ${s.temp_husillo_C})` };

const f = (msg.payload && msg.payload[0]) || {};
msg.payload = (f.promedio != null) ? `Última hora → Promedio ${f.promedio} | Máx ${f.maximo} | Mín ${f.minimo}` : "Reuniendo lecturas...";
return msg;

let seg = flow.get("seg_uso", "file") || 0;
if (flow.get("cnc_on") === true) seg++;
flow.set("seg_uso", seg, "file");
return { payload: `Uso: ${seg} s | Mantenimiento: ${seg >= 60 ? "PENDIENTE" : "al día"}` };

const s = flow.get("sensores");
if (!s) return null;
let h = context.get("hist") || [];
h.push(s.temp_husillo_C);
if (h.length > 20) h.shift();
context.set("hist", h);
if (h.length < 20) return { payload: `Reuniendo datos (${h.length}/20)...` };
const a = h.slice(0, 10).reduce((x, y) => x + y, 0) / 10;
const b = h.slice(10).reduce((x, y) => x + y, 0) / 10;
const sube = b - a;
const avisar = sube > 2 && b > 50;
return { payload: `Tendencia: ${sube > 0 ? "+" : ""}${sube.toFixed(2)} | ${avisar ? "AVISO: sube rápido, revisar" : "estable"}` };

let estado = flow.get("celda_ae2") || {
    fase: "reposo", avance: 50, inicioFase: null, duracionCNC: 0,
    piezasTerminadas: 0, alarma: false
};

if (msg.topic === "banda") {
    let luz = Number(msg.payload);
    if (estado.fase === "reposo" && Number.isFinite(luz) && luz < 40) {
        estado.fase = "enBanda";
        estado.inicioFase = Date.now();
    }
} else if (msg.topic === "avance") {
    let v = Number(msg.payload);
    if (Number.isFinite(v)) estado.avance = v;
} else if (msg.topic === "tick") {
    let ahora = Date.now();
    if (estado.fase === "enBanda" && ahora - estado.inicioFase >= 3000) {
        estado.fase = "enCNC";
        estado.inicioFase = ahora;
        estado.duracionCNC = 2000 + (estado.avance / 10) * 1000;
    } else if (estado.fase === "enCNC" && ahora - estado.inicioFase >= estado.duracionCNC) {
        estado.fase = "reposo";
        estado.piezasTerminadas++;
        estado.inicioFase = null;
    }
    estado.alarma = estado.fase === "enCNC" && (ahora - estado.inicioFase >= 12000);
}

flow.set("celda_ae2", estado);

return [
    { payload: estado.fase === "enBanda" ? 1 : 0 },
    { payload: estado.fase === "enCNC" ? 1 : 0 },
    { payload: `Fase: ${estado.fase} | Banda: ${estado.fase === "enBanda" ? "ON" : "OFF"} | CNC: ${estado.fase === "enCNC" ? "ON" : "OFF"} | Avance: ${estado.avance}% | Piezas: ${estado.piezasTerminadas} | Alarma: ${estado.alarma ? "ATASCO (>12s)" : "Normal"}` }
];
